<?php

namespace Database\Seeders;

use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;
use RuntimeException;

class MorelosPostalSettlementsSeeder extends Seeder
{
    /*
     * Snapshot compacto de los registros SEPOMEX de Morelos importados localmente.
     * El contenido es gzip + base64 para no depender del TXT en producción.
     */
    private const PAYLOAD = '';

    public function run(): void
    {
        $decoded = base64_decode(self::PAYLOAD, true);

        if ($decoded === false) {
            throw new RuntimeException('No se pudo decodificar el snapshot SEPOMEX de Morelos.');
        }

        $csv = gzdecode($decoded);

        if ($csv === false) {
            throw new RuntimeException('No se pudo descomprimir el snapshot SEPOMEX de Morelos.');
        }

        $lines = preg_split('/\r\n|\r|\n/', trim($csv));
        $header = str_getcsv((string) array_shift($lines), '|');
        $rows = [];
        $now = now();

        foreach ($lines as $line) {
            if (trim($line) === '') {
                continue;
            }

            $values = str_getcsv($line, '|');
            $row = array_combine($header, $values);

            if ($row === false) {
                throw new RuntimeException('El snapshot SEPOMEX contiene una fila inválida.');
            }

            foreach ($row as $key => $value) {
                $row[$key] = $value === '' ? null : $value;
            }

            $row['created_at'] = $now;
            $row['updated_at'] = $now;
            $rows[] = $row;
        }

        DB::table('postal_settlements')->upsert(
            $rows,
            ['source', 'state_code', 'municipality_code', 'settlement', 'postal_code'],
            ['state', 'municipality', 'settlement_type', 'city', 'zone', 'updated_at']
        );

        $this->command?->info('Morelos postal settlements seeded: '.count($rows));
    }
}
